// Static Persian podcast data generated by scripts/fetch-podcasts.mjs
// (iTunes directory + public RSS feeds). Server-safe: no browser APIs.

import data from "@/data/podcasts.json"

export type Episode = {
  id: string
  title: string
  /** ISO date, or null if the feed had no valid pubDate. */
  publishedAt: string | null
  durationSeconds: number | null
  audioUrl: string
  description: string
}

export type Podcast = {
  /** iTunes collectionId as a string. */
  id: string
  title: string
  author: string
  /** 600px artwork URL (is1-ssl.mzstatic.com). */
  artwork: string
  genre: string
  description: string
  feedUrl: string
  /** Latest episodes, newest first. */
  episodes: Episode[]
}

type PodcastsFile = {
  generatedAt: string
  source: string
  podcasts: Podcast[]
}

const podcasts = (data as PodcastsFile).podcasts

export function getPodcasts(): Podcast[] {
  return podcasts
}

export function getPodcast(id: string): Podcast | undefined {
  return podcasts.find((podcast) => podcast.id === id)
}

export function getEpisode(
  podcastId: string,
  episodeId: string
): Episode | undefined {
  return getPodcast(podcastId)?.episodes.find(
    (episode) => episode.id === episodeId
  )
}
